  function openForm(type, id, extra={}) { if(!canEditRecord(type))return alert(`${currentRole()} access is read-only for this action. Ask a workspace administrator to assign the correct role.`);const group={property:'properties',unit:'units',owner:'owners',prospect:'prospects',listing:'listings',lease:'leases',payment:'payments',charge:'invoices',municipal:'municipalAccounts','municipal-payment':'municipalAccounts',renewal:'renewals',vendor:'vendors',work:'workOrders',inspection:'inspections',document:'documents',task:'tasks',event:'calendarEvents',member:'teamMembers'}[type];const record=type==='organization'?state.organization:(id&&group?state[group].find(x=>x.id===id):{});$('#modalEyebrow').textContent=type.toUpperCase();$('#modalTitle').textContent=type==='organization'?'Edit company workspace':`${(id&&type!=='municipal-payment')?'Edit':'Add'} ${({property:'property',unit:'unit',owner:'owner',prospect:'prospect',listing:'vacancy listing',lease:'lease & contract',payment:'payment receipt',charge:'finance charge',municipal:'municipal account','municipal-payment':'municipal payment',renewal:'renewal case',vendor:'supplier',work:'work order',inspection:'inspection',document:'document record',task:'management task',event:'property event',member:'team member'})[type]}`;$('#modalBody').innerHTML=formHtml(type,record,extra);$('#modalForm').dataset.type=type;$('#modalForm').dataset.id=id||'';$('#modal').showModal();setupDependentSelections();if(type==='property')setupLocationAssist(); }
  function setupDependentSelections(){
    const form=$('#modalForm'), propertySelect=form.querySelector('select[name="propertyId"]'),unitSelect=form.querySelector('select[name="unitId"]');
    if(propertySelect&&unitSelect){const apply=()=>{const selected=propertySelect.value;[...unitSelect.options].forEach(option=>{if(!option.value)return;const u=unit(option.value);option.hidden=!!selected&&u?.propertyId!==selected;});const selectedUnit=unit(unitSelect.value);if(selectedUnit&&selected&&selectedUnit.propertyId!==selected)unitSelect.value='';};propertySelect.addEventListener('change',apply);apply();}
    const leaseSelect=form.querySelector('select[name="leaseId"]'), chargeSelect=form.querySelector('select[name="chargeId"]'), paymentAmount=form.querySelector('[name="amount"]');
    if(chargeSelect&&paymentAmount){chargeSelect.addEventListener('change',()=>{const c=state.invoices.find(item=>item.id===chargeSelect.value);if(c){paymentAmount.value=chargeBalance(c).toFixed(2);if(leaseSelect)leaseSelect.value=c.leaseId;}});}
    const rent=form.querySelector('[name="rentAmount"]');
    if(leaseSelect&&rent){const update=()=>{const l=lease(leaseSelect.value);if(l&&!rent.dataset.changed){rent.value=number(l.monthlyRent).toFixed(2);}calculateBillingForm(form);};leaseSelect.addEventListener('change',update);rent.addEventListener('input',()=>{rent.dataset.changed='yes';calculateBillingForm(form);});['waterAmount','electricityAmount','wifiAmount','parkingAmount','otherAmount','creditAmount'].forEach(name=>form.querySelector(`[name="${name}"]`)?.addEventListener('input',()=>calculateBillingForm(form)));calculateBillingForm(form);}
  }
  function calculateBillingForm(form){
    const get=name=>number(form.querySelector(`[name="${name}"]`)?.value), charges=get('rentAmount')+get('waterAmount')+get('electricityAmount')+get('wifiAmount')+get('parkingAmount')+get('otherAmount'), credits=get('creditAmount'), net=Math.max(0,charges-credits), amount=form.querySelector('[name="amount"]');
    if(amount)amount.value=net.toFixed(2); const write=(id,value)=>{const el=form.querySelector(id);if(el)el.textContent=money(value);};write('#billingCharges',charges);write('#billingCredits',credits);write('#billingNet',net);
  }
  function setupLocationAssist(){
    const form=$('#modalForm'), input=$('#propertyAddress'), list=$('#addressSuggestions'), locality=form.querySelector('[name="locality"]'), country=form.querySelector('[name="country"]'), lat=form.querySelector('[name="latitude"]'), lon=form.querySelector('[name="longitude"]'), source=form.querySelector('[name="locationSource"]'), accuracy=form.querySelector('[name="locationAccuracyM"]'), verified=form.querySelector('[name="locationVerifiedAt"]'), status=$('#locationStatus');
    if(!input)return; let timer,map,marker;
    const number=value=>Number.parseFloat(value), valid=()=>Number.isFinite(number(lat.value))&&Number.isFinite(number(lon.value));
    const mapUrl=()=>`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(`${lat.value},${lon.value}`)}`;
    const setStatus=(text,kind='')=>{status.textContent=text;status.className=`location-status ${kind}`;};
    const describe=()=>valid()?`${Number(lat.value).toFixed(6)}, ${Number(lon.value).toFixed(6)}${source.value?` · ${source.value}`:''}`:'No precise pin set yet. You can still save the property and add one later.';
    const updateMap=(move=true)=>{if(!map||!valid())return;if(marker)marker.setLatLng([number(lat.value),number(lon.value)]);else {marker=window.L.marker([number(lat.value),number(lon.value)],{draggable:true}).addTo(map);marker.on('dragend',()=>setPoint(marker.getLatLng().lat,marker.getLatLng().lng,'Map pin'));}if(move)map.setView([number(lat.value),number(lon.value)],17);setStatus(describe(),'ready');};
    const setPoint=(nextLat,nextLon,method='Map pin',gpsAccuracy='')=>{lat.value=number(nextLat).toFixed(6);lon.value=number(nextLon).toFixed(6);source.value=method;accuracy.value=gpsAccuracy?Number(gpsAccuracy).toFixed(0):'';verified.value=new Date().toISOString();updateMap();};
    const choose=place=>{input.value=place.display_name||input.value;setPoint(place.lat,place.lon,place.source||'Smart address search');const a=place.address||{};locality.value=a.suburb||a.city_district||a.city||a.town||a.village||locality.value;country.value=a.country||country.value;list.innerHTML='';};
    const normalisePhoton=feature=>{const p=feature.properties||{},coords=feature.geometry?.coordinates||[];const bits=[p.name,p.street&&p.housenumber?`${p.housenumber} ${p.street}`:p.street,p.district||p.city||p.county,p.country].filter((value,index,all)=>value&&all.indexOf(value)===index);return {display_name:bits.join(', '),lat:coords[1],lon:coords[0],source:'Smart address search',address:{suburb:p.district||'',city:p.city||p.county||'',town:p.city||'',country:p.country||''}};};
    const searchPhoton=async query=>{const r=await fetch(`https://photon.komoot.io/api/?limit=7&lang=en&q=${encodeURIComponent(query)}`);if(!r.ok)throw new Error('Photon search unavailable');const data=await r.json();return (data.features||[]).map(normalisePhoton).filter(p=>Number.isFinite(number(p.lat))&&Number.isFinite(number(p.lon)));};
    const searchNominatim=async query=>{const inNamibia=/namibia/i.test(country.value||'');const r=await fetch(`https://nominatim.openstreetmap.org/search?format=jsonv2&addressdetails=1&limit=7${inNamibia?'&countrycodes=na':''}&q=${encodeURIComponent(query)}`,{headers:{'Accept-Language':'en'}});if(!r.ok)throw new Error('Backup search unavailable');return r.json();};
    const show=places=>{list.innerHTML='';places.forEach(place=>{const button=document.createElement('button');button.type='button';button.className='address-choice';button.innerHTML=`<b>${esc(place.display_name||'Unnamed location')}</b><span>${Number(place.lat).toFixed(6)}, ${Number(place.lon).toFixed(6)}</span>`;button.onclick=()=>choose(place);list.append(button);});if(!places.length)list.innerHTML='<p class="form-help">No exact result. Click the map, use device GPS, or type coordinates below.</p>';};
    const reverse=async(nextLat,nextLon,method,gpsAccuracy='')=>{setPoint(nextLat,nextLon,method,gpsAccuracy);try{const r=await fetch(`https://nominatim.openstreetmap.org/reverse?format=jsonv2&addressdetails=1&lat=${encodeURIComponent(nextLat)}&lon=${encodeURIComponent(nextLon)}`,{headers:{'Accept-Language':'en'}});if(!r.ok)throw new Error();const place=await r.json();input.value=place.display_name||input.value;const a=place.address||{};locality.value=a.suburb||a.city_district||a.city||a.town||a.village||locality.value;country.value=a.country||country.value;}catch{setStatus(`${describe()} · Address details could not be matched automatically; the coordinates are saved.`,'ready');}};
    if(window.L){const initial=valid()?[number(lat.value),number(lon.value)]:[-22.5609,17.0658];map=window.L.map('propertyLocationMap',{scrollWheelZoom:false}).setView(initial,valid()?17:12);window.L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap contributors'}).addTo(map);map.on('click',event=>reverse(event.latlng.lat,event.latlng.lng,'Map pin'));if(valid())updateMap(false);else setStatus(describe());setTimeout(()=>map.invalidateSize(),100);}else{const holder=$('#propertyLocationMap');holder.classList.add('map-unavailable');holder.textContent='The map library could not load. You can still use address search, device GPS or coordinates.';}
    input.addEventListener('input',()=>{clearTimeout(timer);const q=input.value.trim();list.innerHTML='';if(q.length<3)return;timer=setTimeout(async()=>{const scoped=/namibia/i.test(country.value||'')?`${q}, Namibia`:q;try{let places=await searchPhoton(scoped);if(!places.length)places=await searchNominatim(scoped);show(places);}catch{try{show(await searchNominatim(scoped));}catch{list.innerHTML='<p class="form-help">Address suggestions are temporarily unavailable. Use device GPS, click the map, or enter the coordinates.</p>';}}},400);});
    [lat,lon].forEach(field=>field.addEventListener('change',()=>{if(valid()){source.value=source.value||'Manual coordinates';verified.value=new Date().toISOString();updateMap();}else setStatus('Enter both a valid latitude and longitude, or use the map.','');}));
    $('#centerPropertyMap')?.addEventListener('click',()=>{if(map)map.setView(valid()?[number(lat.value),number(lon.value)]:[-22.5609,17.0658],valid()?17:12);});
    $('#previewPropertyMap')?.addEventListener('click',()=>{if(!valid())return alert('Choose an address suggestion, use device GPS, click the map or enter both coordinates first.');window.open(mapUrl(),'_blank','noopener');});
    $('#useCurrentLocation')?.addEventListener('click',()=>{if(!navigator.geolocation)return alert('Location is not supported by this browser.');setStatus('Reading your device GPS…','loading');navigator.geolocation.getCurrentPosition(position=>reverse(position.coords.latitude,position.coords.longitude,'Device GPS',position.coords.accuracy),()=>setStatus('MBM could not read the device GPS. Allow location access, then try again, or use the map pin.','error'),{enableHighAccuracy:true,timeout:15000,maximumAge:30000});});
  }
  function fields(form) { return Object.fromEntries(new FormData(form).entries()); }
  function addOrUpdate(group, item, id) { if(id){const i=state[group].findIndex(x=>x.id===id);state[group][i]={...state[group][i],...item,updatedAt:today()};return state[group][i];} const saved={id:uid(group.slice(0,-1)),...item,createdAt:today()};state[group].push(saved);return saved; }
  function openAgreementCase(id='',extra={}){if(!['Administrator','Local administrator','Property Manager','Finance','Legal'].includes(currentRole()))return alert(`${currentRole()} access is read-only for agreement cases.`);const record=id?(state.agreementCases||[]).find(item=>item.id===id)||{}:{};$('#modalEyebrow').textContent='AGREEMENT CASE';$('#modalTitle').textContent=id?'Review negotiation / arrangement':'Open agreement negotiation / arrangement';$('#modalBody').innerHTML=formHtml('agreement-case',record,extra);$('#modalForm').dataset.type='agreement-case';$('#modalForm').dataset.id=id;$('#modal').showModal();}
  function saveAgreementCase(){const form=$('#modalForm'),id=form.dataset.id,data=fields(form);if(!data.leaseId||!data.caseType||!data.status)return alert('Select the agreement, case type and current status.');['proposedAmount','agreedAmount'].forEach(key=>data[key]=number(data[key]));const saved=addOrUpdate('agreementCases',data,id);audit(state,id?'Agreement case updated':'Agreement case opened',`${leaseName(saved.leaseId)} · ${saved.caseType} · ${saved.status}`);save('Agreement case saved');$('#modal').close();render();}
  async function saveForm(e) { e.preventDefault(); const form=$('#modalForm'), type=form.dataset.type, id=form.dataset.id, data=fields(form); let saved;
    if(type==='organization'){if(!data.name)return alert('Enter the company legal name.');state.organization={...state.organization,...data};audit(state,'Company workspace updated',data.name);save('Company profile updated');$('#modal').close();render();return;}
    if(type==='property'){ if(!data.code||!data.name) return alert('Enter the property/ERF code and property name.');saved=addOrUpdate('properties',data,id);audit(state,id?'Property updated':'Property created',propertyName(saved.id)); }
    if(type==='unit'){if(!data.propertyId||!data.name)return alert('Select a property and enter the unit/rental area.');data.marketRent=Number(data.marketRent||0);saved=addOrUpdate('units',data,id);audit(state,id?'Unit updated':'Unit created',`${propertyName(saved.propertyId)} · ${saved.name}`);}
    if(type==='owner'){if(!data.name)return alert('Enter the owner name.');data.managementFeePct=Number(data.managementFeePct||0);saved=addOrUpdate('owners',data,id);audit(state,id?'Owner updated':'Owner added',saved.name);}
    if(type==='prospect'){if(!data.name)return alert('Enter the prospect name.');saved=addOrUpdate('prospects',data,id);audit(state,id?'Prospect updated':'Prospect added',saved.name);}
    if(type==='listing'){if(!data.unitId)return alert('Select a vacant unit.');data.askingRent=Number(data.askingRent||0);saved=addOrUpdate('listings',data,id);audit(state,id?'Vacancy listing updated':'Vacancy listing created',unit(saved.unitId)?.name||'Unit');}
    if(type==='lease'){if(!data.tenantName||!data.propertyId||!data.unitId||!data.leaseNo)return alert('Enter tenant, property, unit and agreement reference.');if(data.status==='Active'&&data.approvalStatus==='Rejected')return alert('A rejected agreement cannot be activated. Record an approved agreement or keep it as Draft / Pending approval.');let c=id?contact(lease(id).contactId):null;if(c){c.name=data.tenantName;c.phone=data.tenantPhone;}else{c={id:uid('contact'),name:data.tenantName,phone:data.tenantPhone,email:'',kind:'Tenant',createdAt:today()};state.contacts.push(c);}data.contactId=c.id;delete data.tenantName;delete data.tenantPhone;['monthlyRent','escalation','deposit','noticeDays'].forEach(k=>data[k]=Number(data[k]||0));saved=addOrUpdate('leases',data,id);const u=unit(saved.unitId);if(u)u.status=activeStatus(saved.status)?'Occupied':u.status;audit(state,id?'Agreement updated':'Agreement created',`${leaseName(saved.id)} · ${saved.approvalStatus||'Legacy approval'} · ${saved.billingStatus||'Legacy billing'}`);}
    if(type==='payment'){if(!data.leaseId||!data.amount)return alert('Select the lease and enter the received amount.');data.amount=Number(data.amount);data.propertyId=lease(data.leaseId)?.propertyId||'';if(data.chargeId){const c=state.invoices.find(x=>x.id===data.chargeId);if(!c||c.leaseId!==data.leaseId)return alert('The selected charge must belong to the payment lease.');if(data.amount>chargeBalance(c)+.009)return alert(`The payment exceeds the selected charge balance of ${money(chargeBalance(c))}. Leave it unallocated or record a separate charge.`);}saved=addOrUpdate('payments',data,id);if(data.chargeId){const old=state.allocations.find(a=>a.paymentId===saved.id&&a.chargeId===data.chargeId);if(old)old.amount=saved.amount;else state.allocations.push({id:uid('allocation'),paymentId:saved.id,chargeId:data.chargeId,amount:saved.amount,createdAt:today()});}audit(state,id?'Payment updated':'Payment recorded',`${saved.receiptNo} · ${money(saved.amount)}`);}
    if(type==='charge'){
      if(!data.leaseId)return alert('Select the agreement that this invoice belongs to.');
      const components=[['Monthly rent','Rent','rentAmount'],['Water recovery','Utilities','waterAmount'],['Electricity recovery','Utilities','electricityAmount'],['Wi-Fi / internet','Utilities','wifiAmount'],['Parking','Parking','parkingAmount'],['Other approved charge','Other','otherAmount'],['Credit / deduction','Credit','creditAmount']];
      data.lineItems=components.map(([description,category,key])=>({description,category,amount:key==='creditAmount'?-Math.abs(number(data[key])):number(data[key])})).filter(item=>Math.abs(item.amount)>0.0009);
      const breakdown=invoiceBreakdown(data); if(!data.lineItems.length||breakdown.net<=0)return alert('Enter at least one charge greater than the credits.');
      data.invoiceNo=String(data.invoiceNo||'').trim()||`INV-${today().replaceAll('-','')}-${String(state.invoices.length+1).padStart(4,'0')}`;
      if(state.invoices.some(item=>item.invoiceNo===data.invoiceNo&&item.id!==id))return alert('That invoice number already exists. Use a unique invoice number.');
      if(data.billingPeriod&&state.invoices.some(item=>item.leaseId===data.leaseId&&item.billingPeriod===data.billingPeriod&&item.id!==id&&String(item.type||'').toLowerCase()==='rent'))return alert(`A rent invoice already exists for this agreement for ${data.billingPeriod}. Open that invoice instead of creating a duplicate.`);
      data.amount=breakdown.net;data.propertyId=lease(data.leaseId)?.propertyId||'';data.status='Open';saved=addOrUpdate('invoices',data,id);audit(state,id?'Invoice updated':'Invoice created',`${data.invoiceNo} · ${leaseName(data.leaseId)} · ${money(data.amount)}`);
    }
    if(type==='municipal'){if(!data.propertyId||data.balance==='')return alert('Select a property and enter the current municipal debt.');['balance','agreementTotal','arrangementBalance','monthlyInstallment'].forEach(k=>data[k]=Number(data[k]||0));if(data.arrangementStatus==='Active'&&(!data.collectorName||!data.agreementTotal||!data.monthlyInstallment||!data.nextArrangementDue))return alert('For an active repayment agreement, enter the debt collector, agreed amount, monthly instalment and next instalment date.');const existing=state.municipalAccounts.find(m=>m.propertyId===data.propertyId&&m.id!==id);saved=addOrUpdate('municipalAccounts',data,id||existing?.id);audit(state,'Municipal account saved',`${propertyName(data.propertyId)} · debt ${money(data.balance)}${data.arrangementStatus!=='No arrangement'?` · ${data.arrangementStatus} arrangement ${money(data.arrangementBalance)}`:''}`);}
    if(type==='municipal-payment'){const account=state.municipalAccounts.find(m=>m.id===id);if(!account||!data.amount)return alert('Enter the amount paid.');data.amount=Number(data.amount);if(data.amount>Number(account.balance||0)+.009)return alert(`Payment is greater than the current account balance of ${money(account.balance)}.`);account.balance=Math.max(0,Number(account.balance||0)-data.amount);state.municipalPayments.push({id:uid('municipalPayment'),accountId:account.id,propertyId:account.propertyId,...data,createdAt:today()});audit(state,'Municipal payment recorded',`${propertyName(account.propertyId)} · ${money(data.amount)}`);}
    if(type==='renewal'){if(!data.leaseId)return alert('Select the lease contract.');['termMonths','proposedRent'].forEach(k=>data[k]=Number(data[k]||0));saved=addOrUpdate('renewals',data,id);if(data.stage==='Renewed / billing activated'){const l=lease(data.leaseId);if(!['Approved by legal'].includes(data.legalStatus)||data.approvalStatus!=='Approved'||!data.agreementRef||!data.signatureDate||!data.billingDate||!data.proposedRent||!data.termMonths){return alert('Renewal activation requires legal approval, management approval, agreement reference, signature date, billing activation date, term and proposed rent.');}const end=new Date(`${l.endDate||today()}T00:00:00`);l.startDate=data.billingDate;l.endDate=new Date(end.setMonth(end.getMonth()+Number(data.termMonths))).toISOString().slice(0,10);l.monthlyRent=Number(data.proposedRent);l.leaseNo=data.agreementRef;l.status='Active';}audit(state,id?'Renewal updated':'Renewal case created',leaseName(data.leaseId));}
    if(type==='vendor'){if(!data.name)return alert('Enter the supplier name.');saved=addOrUpdate('vendors',data,id);audit(state,id?'Supplier updated':'Supplier added',saved.name);}
    if(type==='work'){if(!data.propertyId||!data.title)return alert('Select a property and enter a work order title.');['quotedAmount','actualCost'].forEach(k=>data[k]=Number(data[k]||0));data.status=id?state.workOrders.find(x=>x.id===id).status:'Open';saved=addOrUpdate('workOrders',data,id);audit(state,id?'Work order updated':'Work order created',data.title);}
    if(type==='inspection'){if(!data.propertyId||!data.date)return alert('Select a property and date.');data.status=id?state.inspections.find(x=>x.id===id).status:'Scheduled';saved=addOrUpdate('inspections',data,id);audit(state,id?'Inspection updated':'Inspection scheduled',data.type);}
    if(type==='document'){const file=form.querySelector('input[name="file"]')?.files?.[0];delete data.file;if(file){const linkedLease=lease(data.leaseId);const result=await window.MBMCloudV10?.uploadPrivateDocument?.(file,{leaseNo:linkedLease?.leaseNo,propertyCode:property(data.propertyId||linkedLease?.propertyId)?.code});if(!result?.ok)return alert(`Private upload failed: ${result?.message||'Sign in to Supabase first.'}`);data.storagePath=result.path;if(!data.name)data.name=file.name;data.uploadedAt=new Date().toISOString();}if(!data.name)return alert('Enter a document file/name or choose a file.');if(!id&&!data.uploadedAt)data.uploadedAt=new Date().toISOString();saved=addOrUpdate('documents',data,id);audit(state,id?'Document record updated':'Document registered',`${data.name} · ${dateTimeLabel(saved.uploadedAt||saved.createdAt)}`);}
    if(type==='task'){if(!data.title||!data.date)return alert('Enter a task and due date.');data.status=id?state.tasks.find(x=>x.id===id).status:'Open';saved=addOrUpdate('tasks',data,id);audit(state,id?'Task updated':'Task added',data.title);}
    if(type==='event'){if(!data.title||!data.date)return alert('Enter the event title and date.');saved=addOrUpdate('calendarEvents',data,id);audit(state,id?'Property event updated':'Property event added',data.title);}
    if(type==='member'){if(!data.name||!data.role)return alert('Enter the team member and role.');saved=addOrUpdate('teamMembers',data,id);audit(state,id?'Team role updated':'Team role staged',`${data.name} · ${data.role}`);}
    save('Saved');$('#modal').close();render();
  }
  function generateMonthlyRentInvoices(){
    const period=billingMonth(); const eligible=billableAgreements().filter(l=>!l.startDate||l.startDate.slice(0,7)<=period).filter(l=>!l.endDate||l.endDate.slice(0,7)>=period);
    const missing=eligible.filter(l=>!state.invoices.some(invoice=>invoice.leaseId===l.id&&invoice.billingPeriod===period&&String(invoice.type||'').toLowerCase()==='rent'));
    if(!missing.length)return alert(`All billable active agreements already have a rent invoice for ${period}. Check agreements that are still On hold, Suspended or awaiting approval. No duplicates were created.`);
    if(!confirm(`Create ${missing.length} monthly rent invoice(s) for ${period}? Each invoice will use the current contractual rent on its linked agreement.`))return;
    const dueDate=`${period}-05`;
    missing.forEach((l,index)=>{const amount=number(l.monthlyRent);if(!amount)return;state.invoices.push({id:uid('invoice'),invoiceNo:`INV-${period.replace('-','')}-${String(state.invoices.length+index+1).padStart(4,'0')}`,leaseId:l.id,propertyId:l.propertyId,type:'Rent',billingPeriod:period,chargeDate:today(),dueDate,description:`Monthly rent · ${new Intl.DateTimeFormat('en-NA',{month:'long',year:'numeric'}).format(new Date(`${period}-01T00:00:00`))}`,lineItems:[{description:'Monthly rent',category:'Rent',amount}],rentAmount:amount,amount,status:'Open',notes:'Generated from the active agreement',createdAt:today()});});
    audit(state,'Monthly rent invoices generated',`${missing.length} invoice(s) prepared for ${period}.`);save('Monthly rent invoices generated');render();
  }
  function whatsapp(id) { const p=state.payments.find(x=>x.id===id),l=lease(p?.leaseId),c=contact(l?.contactId);if(!p||!c?.phone)return alert('A tenant contact number is required before opening WhatsApp.');const number=String(c.phone).replace(/\D/g,'').replace(/^0/,'264');const message=`Hello ${c.name}, MBM confirms receipt ${p.receiptNo} for ${money(p.amount)} on ${dateLabel(p.paymentDate)}. Rental period: ${p.period||'—'}. Thank you.`;window.open(`https://wa.me/${number}?text=${encodeURIComponent(message)}`,'_blank','noopener');}
  function invoiceDetails(id) { const invoice=state.invoices.find(item=>item.id===id); if(!invoice)return null; const agreement=lease(invoice.leaseId), tenant=contact(agreement?.contactId), rentalUnit=unit(agreement?.unitId), propertyRecord=property(invoice.propertyId||agreement?.propertyId); return {invoice,agreement,tenant,rentalUnit,propertyRecord,balance:chargeBalance(invoice)}; }
  function invoiceMessage(details) { const {invoice,tenant,propertyRecord,rentalUnit,balance}=details; return `Hello ${tenant?.name||'Tenant'},\n\n${state.organization.shortName||'MBM Property'} has issued invoice ${invoice.invoiceNo||'—'} for ${money(invoice.amount)}.\nProperty / unit: ${propertyRecord?.name||'—'}${rentalUnit?` · ${rentalUnit.name}`:''}\nDue date: ${dateLabel(invoice.dueDate)}\nOutstanding balance: ${money(balance)}\n\nPlease see the attached invoice. Contact us if you have any questions.\n\n${state.organization.name||'Musa Business Management CC'}`; }
  function logInvoiceCommunication(details,channel,status='Prepared') { const {invoice,tenant}=details; state.communications.unshift({id:uid('communication'),createdAt:new Date().toISOString(),invoiceId:invoice.id,invoiceNo:invoice.invoiceNo||'',leaseId:invoice.leaseId,propertyId:invoice.propertyId||'',recipient:tenant?.name||'',recipientPhone:tenant?.phone||'',recipientEmail:tenant?.email||'',channel,status}); audit(state,`Invoice ${channel.toLowerCase()} ${status.toLowerCase()}`,`${invoice.invoiceNo||'Invoice'} · ${tenant?.name||'No recipient'}`); save(`Invoice ${channel.toLowerCase()} prepared`); }
  function invoiceDocument(details) { const {invoice,agreement,tenant,rentalUnit,propertyRecord,balance}=details, org=state.organization||{}, issued=invoice.chargeDate||invoice.createdAt?.slice(0,10)||today(); return `<!doctype html><html><head><meta charset="utf-8"><title>Invoice ${esc(invoice.invoiceNo||'MBM invoice')}</title><style>body{margin:0;background:#edf3f7;color:#263b4d;font:14px Aptos,Arial,sans-serif}.page{box-sizing:border-box;max-width:820px;min-height:1020px;margin:28px auto;background:#fff;padding:52px 56px;box-shadow:0 4px 20px #18395020}.top{display:flex;justify-content:space-between;gap:25px;border-bottom:4px solid #c6922a;padding-bottom:24px}.brand h1{margin:0;color:#12395f;font-size:25px}.brand p,.muted{color:#617789;line-height:1.5}.invoice-title{text-align:right}.invoice-title strong{display:block;color:#12395f;font-size:30px;letter-spacing:.04em}.invoice-title span{display:block;margin-top:5px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:28px;margin:32px 0}.label{display:block;color:#688094;text-transform:uppercase;font-size:10px;font-weight:800;letter-spacing:.08em;margin-bottom:7px}.value{font-size:15px;font-weight:700;color:#163e5e}.box{border:1px solid #d6e1e8;border-radius:8px;padding:16px;background:#fbfdfe}.box p{margin:4px 0}.invoice{width:100%;border-collapse:collapse;margin-top:25px}.invoice th{background:#12395f;color:#fff;text-align:left;padding:12px;font-size:11px;text-transform:uppercase;letter-spacing:.05em}.invoice td{padding:15px 12px;border-bottom:1px solid #dfe7ec;vertical-align:top}.invoice .amount{text-align:right;white-space:nowrap}.total{margin-left:auto;margin-top:22px;width:300px}.total div{display:flex;justify-content:space-between;padding:8px 0;border-bottom:1px solid #e3e9ed}.total .grand{font-size:18px;font-weight:800;color:#12395f;border-bottom:3px solid #c6922a}.notice{margin-top:36px;padding:15px 17px;border-left:4px solid #c6922a;background:#fff8e7;color:#5c4a20;line-height:1.5}.footer{margin-top:48px;padding-top:15px;border-top:1px solid #dfe7ec;color:#6c8191;font-size:11px;line-height:1.5}.print{position:fixed;right:20px;top:18px;border:0;border-radius:8px;background:#12395f;color:#fff;padding:11px 15px;font-weight:700;cursor:pointer}@media print{body{background:#fff}.page{box-shadow:none;margin:0;max-width:none}.print{display:none}}@media(max-width:640px){.page{padding:28px 22px;margin:0}.top,.grid{display:block}.invoice-title{text-align:left;margin-top:22px}.grid .box{margin-bottom:15px}}</style></head><body><button class="print" onclick="window.print()">Print / Save PDF</button><main class="page"><header class="top"><div class="brand"><h1>${esc(org.name||'Musa Business Management CC')}</h1><p>${esc(org.shortName||'MBM Property')}<br>${esc(org.notes||'Property & rental management')}</p></div><div class="invoice-title"><strong>INVOICE</strong><span><b>${esc(invoice.invoiceNo||'—')}</b></span><span class="muted">Issued ${dateLabel(issued)}<br>Due ${dateLabel(invoice.dueDate)}</span></div></header><section class="grid"><div class="box"><span class="label">Bill to</span><p class="value">${esc(tenant?.name||'Tenant not recorded')}</p><p>${esc(tenant?.phone||'')}</p><p>${esc(tenant?.email||'')}</p></div><div class="box"><span class="label">Property / agreement</span><p class="value">${esc(propertyRecord?.name||propertyName(invoice.propertyId||agreement?.propertyId))}</p><p>${esc(rentalUnit?.name||'Unit not recorded')}</p><p>${esc(agreement?.leaseNo||'Agreement reference not recorded')}</p></div></section><table class="invoice"><thead><tr><th>Description</th><th>Charge type</th><th class="amount">Amount</th></tr></thead><tbody><tr><td><b>${esc(invoice.description||invoice.type||'Rental charge')}</b><br><span class="muted">${esc(invoice.notes||'')}</span></td><td>${esc(invoice.type||'Rent')}</td><td class="amount">${money(invoice.amount)}</td></tr></tbody></table><section class="total"><div><span>Invoice total</span><b>${money(invoice.amount)}</b></div><div><span>Payments allocated</span><b>${money(Number(invoice.amount||0)-balance)}</b></div><div class="grand"><span>Amount due</span><span>${money(balance)}</span></div></section><section class="notice"><b>Payment instruction</b><br>Please quote invoice reference <b>${esc(invoice.invoiceNo||'—')}</b> when paying. Save this page as a PDF, then attach it to your approved WhatsApp or email message.</section><footer class="footer">Generated from ${esc(org.shortName||'MBM Property')} on ${new Date().toLocaleString('en-NA')}. This invoice is linked to the recorded property, agreement and payment allocation in the MBM workspace.</footer></main></body></html>`; }
  function openInvoice(id) { const details=invoiceDetails(id); if(!details)return alert('Invoice record not found.'); const win=window.open('','_blank'); if(!win)return alert('Your browser blocked the invoice window. Allow pop-ups for this site and try again.'); win.document.write(invoiceDocument(details));win.document.close(); }
  function sendInvoiceWhatsApp(id) { const details=invoiceDetails(id); if(!details)return alert('Invoice record not found.'); if(!details.tenant?.phone)return alert('Add the tenant’s WhatsApp/contact number to the agreement before preparing this message.'); openInvoice(id); const number=String(details.tenant.phone).replace(/\D/g,'').replace(/^0/,'264'); window.open(`https://wa.me/${number}?text=${encodeURIComponent(invoiceMessage(details))}`,'_blank','noopener'); logInvoiceCommunication(details,'WhatsApp','Prepared'); alert('The invoice opened in a new window and WhatsApp opened with a prepared message. Choose Print / Save PDF on the invoice, then attach that PDF in WhatsApp and review before sending.'); }
  function sendInvoiceEmail(id) { const details=invoiceDetails(id); if(!details)return alert('Invoice record not found.'); if(!details.tenant?.email)return alert('Add the tenant’s email address to the agreement before preparing this email.'); openInvoice(id); const subject=`Invoice ${details.invoice.invoiceNo||''} from ${state.organization.shortName||'MBM Property'}`; location.href=`mailto:${encodeURIComponent(details.tenant.email)}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(invoiceMessage(details))}`; logInvoiceCommunication(details,'Email','Prepared'); alert('Your email application is opening with a prepared message. Save the invoice PDF from the separate invoice window, then attach it before sending.'); }
  async function copyInvoiceMessage(id) { const details=invoiceDetails(id);if(!details)return alert('Invoice record not found.'); try { await navigator.clipboard.writeText(invoiceMessage(details)); logInvoiceCommunication(details,'Copied message','Prepared'); alert('Invoice message copied. Paste it into WhatsApp, email or another approved channel.'); } catch { alert('Your browser did not allow copying. Open the invoice and use the WhatsApp or email option instead.'); } }
  function openInvoiceSendMenu(id) { const details=invoiceDetails(id), dialog=$('#invoiceDeliveryDialog');if(!details||!dialog)return;dialog.dataset.invoiceId=id;$('#invoiceDeliveryTitle').textContent=`Send invoice ${details.invoice.invoiceNo||''}`;$('#invoiceDeliverySummary').textContent=`${details.tenant?.name||'Tenant not recorded'} · ${money(details.balance)} outstanding · due ${dateLabel(details.invoice.dueDate)}.`;dialog.showModal(); }
  function renewalWhatsapp(id) { const r=state.renewals.find(x=>x.id===id),l=lease(r?.leaseId),c=contact(l?.contactId);if(!r||!c?.phone)return alert('A tenant contact number is required before opening WhatsApp.');const number=String(c.phone).replace(/\D/g,'').replace(/^0/,'264');const message=`Hello ${c.name}, MBM renewal update for ${l?.leaseNo||'your lease'}: stage ${r.stage}. Current contract expiry: ${dateLabel(l?.endDate)}. Next action: ${dateLabel(r.nextActionDate)}. Please contact MBM if you have questions.`;window.open(`https://wa.me/${number}?text=${encodeURIComponent(message)}`,'_blank','noopener');audit(state,'Renewal WhatsApp prepared',`${leaseName(r.leaseId)} · ${r.stage}`);save('Renewal update prepared');}
  function download(name, text, type='application/json') { const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000); }
  function exportCalendar(){const ics=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//MBM//Property Manager//EN'];eventItems().forEach((e,i)=>{if(!e.date)return;ics.push('BEGIN:VEVENT',`UID:mbm-${i}-${e.date}@mbm`,`DTSTAMP:${today().replaceAll('-','')}T000000Z`,`DTSTART;VALUE=DATE:${e.date.replaceAll('-','')}`,`SUMMARY:${String(e.label).replace(/[,;\n]/g,' ')}`,`DESCRIPTION:${String(e.kind).replace(/[,;\n]/g,' ')}`,'END:VEVENT');});ics.push('END:VCALENDAR');download(`MBM-calendar-${today()}.ics`,ics.join('\r\n'),'text/calendar;charset=utf-8');audit(state,'Calendar exported','ICS calendar file created.');save('Calendar exported');}
  function exportMunicipal(){const rows=[['Property','Account number','Statement date','Due date','Balance'],...state.municipalAccounts.map(m=>[propertyName(m.propertyId),m.accountNo||'',m.statementDate||'',m.dueDate||'',m.balance||0])];download(`MBM-municipal-register-${today()}.csv`,rows.map(r=>r.map(x=>`"${String(x??'').replaceAll('"','""')}"`).join(',')).join('\n'),'text/csv');}
  function parseCsvLine(line){const cells=[];let current='',quoted=false;for(let i=0;i<line.length;i++){const char=line[i];if(char==='"'){if(quoted&&line[i+1]==='"'){current+='"';i++;}else quoted=!quoted;}else if(char===','&&!quoted){cells.push(current.trim());current='';}else current+=char;}cells.push(current.trim());return cells;}
  function importHistory(file){const reader=new FileReader();reader.onload=()=>{try{let records=[];const raw=String(reader.result||'').trim();if(file.name.toLowerCase().endsWith('.json'))records=JSON.parse(raw);else{const lines=raw.split(/\r?\n/).filter(Boolean);const headers=parseCsvLine(lines.shift()).map(h=>h.trim().toLowerCase().replace(/\s+/g,'_'));records=lines.map(line=>Object.fromEntries(parseCsvLine(line).map((v,i)=>[headers[i],v])));}if(!Array.isArray(records))throw new Error('The file must contain an array or a CSV with headings.');let added=0,skipped=0;records.forEach((r,index)=>{const receiptNo=r.receipt_no||r.receiptNo||r.receiptnumber||`IMPORT-${today().replaceAll('-','')}-${index+1}`;if(state.payments.some(p=>p.receiptNo===receiptNo)){skipped++;return;}const tenant=String(r.tenant||r.tenant_name||r.customer||'').trim();const unitName=String(r.unit||r.unit_name||'').trim();const l=state.leases.find(x=>contact(x.contactId)?.name===tenant&&(!unitName||unit(x.unitId)?.name===unitName));const amount=Number(r.amount||r.net||r.total||0);if(!amount){skipped++;return;}state.payments.push({id:uid('payment'),receiptNo,leaseId:l?.id||'',propertyId:l?.propertyId||'',paymentDate:r.receipt_date||r.paymentDate||today(),period:[r.month,r.year].filter(Boolean).join(' ')||r.period||'',amount,method:r.payment_method||r.method||'Historical import',notes:r.notes||'',createdAt:today()});added++;});audit(state,'Historical payments imported',`${added} added; ${skipped} skipped or duplicate.`);save('Historical payments imported');render();alert(`${added} payment(s) imported. ${skipped} row(s) skipped.`);}catch(err){alert(`Import failed: ${err.message}`);}};reader.readAsText(file);}
  function exportReport(){const report=state.ui.report||'executive';const rows=[['MBM Property Management Report',report],['Generated',new Date().toLocaleString('en-NA')],[]];if(report==='finance'){rows.push(['Lease/Tenant','Total charges','Payments','Open billed balance']);getActiveLeases().forEach(l=>rows.push([leaseName(l.id),state.invoices.filter(c=>c.leaseId===l.id).reduce((s,c)=>s+Number(c.amount||0),0),state.payments.filter(p=>p.leaseId===l.id).reduce((s,p)=>s+Number(p.amount||0),0),openCharges().filter(c=>c.leaseId===l.id).reduce((s,c)=>s+chargeBalance(c),0)]));}else if(report==='municipal'){rows.push(['Property','Account','Due date','Balance']);state.municipalAccounts.forEach(m=>rows.push([propertyName(m.propertyId),m.accountNo,m.dueDate,m.balance]));}else if(report==='leases'){rows.push(['Lease','Expiry','Days remaining','Renewal stage']);getActiveLeases().forEach(l=>rows.push([leaseName(l.id),l.endDate,diffDays(l.endDate),state.renewals.find(r=>r.leaseId===l.id)?.stage||'No renewal case']));}else if(report==='vacancy'){rows.push(['Property','Unit','Market rent','Listing','Prospects']);state.units.filter(u=>u.status==='Vacant').forEach(u=>{const listing=state.listings.find(x=>x.unitId===u.id);rows.push([propertyName(u.propertyId),u.name,u.marketRent,listing?.status||'Not listed',state.prospects.filter(p=>p.unitId===u.id||(!p.unitId&&p.propertyId===u.propertyId)).length]);});}else if(report==='operations'){rows.push(['Activity','Property','Due','Vendor','Quoted','Actual','Status']);state.workOrders.forEach(w=>rows.push([w.title,propertyName(w.propertyId),w.dueDate,vendor(w.vendorId)?.name||w.assignee||'',w.quotedAmount||0,w.actualCost||0,w.status]));state.inspections.forEach(i=>rows.push([i.type,propertyName(i.propertyId),i.date,i.inspector||'','','',i.status]));}else if(report==='compliance'){rows.push(['Control','Record','Exception','Priority']);complianceIssues().forEach(i=>rows.push([i.kind,i.name,i.detail,i.level]));}else if(report==='documents'){rows.push(['Document','Type','Lease','Property','Status','Review']);state.documents.forEach(d=>rows.push([d.name,d.type,leaseName(d.leaseId),propertyName(d.propertyId),d.status,d.expiryDate]));}else{rows.push(['Metric','Value'],['Properties',state.properties.length],['Units',state.units.length],['Occupancy',`${occupancy().rate}%`],['Active monthly rent',monthlyDue()],['Payments this month',monthPayments()],['Open billed balance',openChargeBalance()],['Municipal exposure',municipalOwing()],['Open compliance exceptions',complianceIssues().length]);}download(`MBM-${report}-report-${today()}.csv`,rows.map(r=>r.map(x=>`"${String(x??'').replaceAll('"','""')}"`).join(',')).join('\n'),'text/csv');}
  function exportReport(){const filters=reportFilters(),data=reportData(state.ui.report||'executive',filters);const scope=filters.propertyId?propertyName(filters.propertyId):'Entire portfolio';const rows=[['MBM Property Management Report',data.title],['Scope',scope],['Period',`${filters.dateFrom||'All dates'} to ${filters.dateTo||'All dates'}`],['Generated',new Date().toLocaleString('en-NA')],[],data.headers,...data.rows];download(`MBM-${String(state.ui.report||'executive')}-report-${today()}.csv`,rows.map(r=>r.map(x=>`"${String(x??'').replaceAll('"','""')}"`).join(',')).join('\n'),'text/csv');audit(state,'Report exported',`${data.title} · ${scope}`);save('Report exported');}
  function bindView(){
    $('#app').onclick=e=>{const button=e.target.closest('button');if(!button)return;const action=button.dataset.action;if(button.dataset.view)return setView(button.dataset.view);if(button.dataset.report){state.ui.report=button.dataset.report;save();render();return;}if(action==='select-property'){state.ui.selectedProperty=button.dataset.id;save('Property workspace selected');render();return;}if(action==='open-map'){const p=property(button.dataset.id);if(!p)return;const query=p.latitude&&p.longitude?`${p.latitude},${p.longitude}`:(p.address||p.name);return window.open(`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(query)}`,'_blank','noopener');}if(action==='form')return openForm(button.dataset.type,button.dataset.id,{propertyId:button.dataset.property,leaseId:button.dataset.lease,unitId:button.dataset.unit});if(action==='receipt')return printReceipt(button.dataset.id);if(action==='whatsapp')return whatsapp(button.dataset.id);if(action==='invoice')return openInvoice(button.dataset.id);if(action==='invoice-send')return openInvoiceSendMenu(button.dataset.id);if(action==='renewal-whatsapp')return renewalWhatsapp(button.dataset.id);if(action==='calendar-export')return exportCalendar();if(action==='municipal-export')return exportMunicipal();if(action==='history-import')return $('#historyFile').click();if(action==='cloud-signin')return window.MBMCloudV10?.signIn();if(action==='cloud-signup')return window.MBMCloudV10?.signUp();if(action==='cloud-save')return window.MBMCloudV10?.save();if(action==='cloud-load')return window.MBMCloudV10?.load();if(action==='cloud-signout')return window.MBMCloudV10?.signOut();if(action==='document-open'){const d=state.documents.find(x=>x.id===button.dataset.id);if(!window.MBMCloudV10?.openPrivateDocument)return alert('The secure document vault is unavailable. Reload the application.');return window.MBMCloudV10.openPrivateDocument(d?.storagePath).then(result=>{if(!result?.ok)alert(result?.message||'Sign in before opening the document.');});}if(action==='complete-work'){const w=state.workOrders.find(x=>x.id===button.dataset.id);w.status=w.status==='Completed'?'Open':'Completed';audit(state,'Work order status changed',`${w.title} → ${w.status}`);save();render();return;}if(action==='complete-inspection'){const i=state.inspections.find(x=>x.id===button.dataset.id);i.status=i.status==='Completed'?'Scheduled':'Completed';audit(state,'Inspection status changed',`${i.type} → ${i.status}`);save();render();return;}if(action==='backup')return backup();if(action==='export-report')return exportReport();if(action==='import')return $('#importFile').click();if(action==='migrate')return legacyMigration();if(action==='reset')return resetWorkspace();};
    $('#propertyScope')?.addEventListener('change',e=>{state.ui.selectedProperty=e.target.value;save('Property workspace selected');render();});
    $('#reportPropertyScope')?.addEventListener('change',e=>{state.ui.reportProperty=e.target.value;save('Report scope updated');render();});
  }
  /* V19 print documents: one visual standard, linked to the financial source of truth. */
  function financialDocument({kind,reference,date,tenant,agreement,rentalUnit,propertyRecord,period,method,lines,charges,credits,net,paid=0,balance=0,notes=''}){
    const org=state.organization||{}, isReceipt=kind==='receipt', title=isReceipt?'RENT PAYMENT RECEIPT':'RENTAL INVOICE', documentLabel=isReceipt?'Receipt No.':'Invoice No.', netLabel=isReceipt?'NET AMOUNT PAID':'NET AMOUNT DUE';
    const lineHtml=lines.map(line=>`<tr><td><b>${esc(line.description)}</b></td><td>${esc(line.category||'Charge')}</td><td class="amount">${money(Math.abs(number(line.amount)))}</td></tr>`).join('')||'<tr><td>Rental charge</td><td>Rent</td><td class="amount">N$ 0.00</td></tr>';
    return `<!doctype html><html><head><meta charset="utf-8"><title>${esc(reference)}</title><style>@page{size:A4;margin:12mm}*{box-sizing:border-box}body{margin:0;background:#edf3f7;color:#283e52;font:14px Aptos,Arial,sans-serif}.page{width:100%;max-width:820px;min-height:1040px;margin:18px auto;background:#f4f8fa;padding:38px 42px;box-shadow:0 5px 22px #153c5f21}.toolbar{position:fixed;right:18px;top:15px;border:0;border-radius:8px;background:#12395f;color:#fff;padding:11px 15px;font-weight:800;cursor:pointer}.mast{display:grid;grid-template-columns:205px 1fr 220px;gap:18px;align-items:center;padding-bottom:19px;border-bottom:5px solid #12395f}.mark{font-weight:900;font-size:39px;letter-spacing:-3px;color:#12395f;line-height:.8}.mark small{display:block;margin-top:10px;font-size:8px;letter-spacing:.1em;color:#c6922a}.title{border-left:2px solid #d19a2a;padding-left:20px}.title h1{margin:0;color:#12395f;font-size:25px;line-height:1.1;letter-spacing:.02em}.title p{margin:8px 0 0;color:#526e82;line-height:1.45;font-size:11px}.document{text-align:right}.document b{display:block;color:#273d4f;font-size:16px}.document span{display:block;margin-top:8px;font-size:11px;color:#536a7d}.people{display:grid;grid-template-columns:1fr 1fr;gap:45px;padding:23px 0 20px}.people h2{margin:0 0 6px;color:#2a4053;font-size:15px}.people p{margin:0;color:#2d4356;font-size:13px;line-height:1.38}.items{width:100%;border-collapse:collapse;background:#f8fbfd}.items th{padding:10px 12px;background:#e9f1f6;border:1px solid #c6d5df;text-align:left;font-size:11px}.items td{padding:11px 12px;border:1px solid #c6d5df;font-size:12px}.items .amount{text-align:right;font-variant-numeric:tabular-nums}.totals{width:420px;margin:26px 0 0 auto}.totals div{display:flex;justify-content:space-between;gap:20px;padding:9px 12px;font-size:14px}.totals .main{background:#12395f;color:#fff;font-size:18px;font-weight:900}.notes{margin-top:27px;padding:13px 0 22px;border-bottom:4px solid #12395f}.notes h3{margin:0 0 5px;font-size:14px}.notes p{margin:0;line-height:1.45;color:#354c5d}.foot{text-align:center;padding:16px 22px;color:#365269;font-size:10px;line-height:1.45}.foot b{display:block;font-size:11px;color:#213d57}@media print{body{background:#fff}.page{margin:0;box-shadow:none;max-width:none}.toolbar{display:none}}@media(max-width:620px){.page{padding:24px 18px}.mast,.people{display:block}.title,.document{margin-top:18px;text-align:left}.totals{width:100%}}</style></head><body><button class="toolbar" onclick="window.print()">Print / Save PDF</button><main class="page"><header class="mast"><div class="mark">MBM<small>PROPERTY · RENTALS · PEACE OF MIND</small></div><div class="title"><h1>${title}</h1><p>${esc(org.name||'Musa Business Management CC')} · Property &amp; Rental Management<br>${esc(propertyRecord?.address||propertyRecord?.name||'Property management')}</p></div><div class="document"><b>${documentLabel} ${esc(reference||'—')}</b><span>${isReceipt?'Receipt':'Issue'} Date: ${dateLabel(date)}${!isReceipt&&balance!==undefined?`<br>Outstanding: ${money(balance)}`:''}</span></div></header><section class="people"><div><h2>${isReceipt?'Payment Received From':'Bill To'}</h2><p><b>${esc(tenant?.name||'Tenant not recorded')}</b><br>${esc(tenant?.phone||'')}<br>${esc(rentalUnit?.name||'Unit not recorded')} · ${esc(propertyRecord?.name||'Property not recorded')}</p></div><div><h2>${isReceipt?'Payment Details':'Invoice Details'}</h2><p>Billing Period: ${esc(period||'—')}<br>${isReceipt?`Payment Method: ${esc(method||'—')}<br>`:''}Contract: ${esc(agreement?.leaseNo||'Not recorded')}<br>Due Date: ${dateLabel(kind==='invoice'?date:undefined)}</p></div></section><table class="items"><thead><tr><th>Description</th><th>Detail</th><th class="amount">Amount (N$)</th></tr></thead><tbody>${lineHtml}</tbody></table><section class="totals"><div><span>Total Charges</span><b>${money(charges)}</b></div><div><span>Deductions / Credits</span><b>${money(credits)}</b></div><div class="main"><span>${netLabel}</span><span>${money(isReceipt?paid:net)}</span></div>${isReceipt?`<div><span>Invoice balance after this receipt</span><b>${money(balance)}</b></div>`:`<div><span>Payments allocated</span><b>${money(net-balance)}</b></div>`}</section><section class="notes"><h3>${isReceipt?'Receipt Notes':'Payment Instruction'}</h3><p>${esc(notes||`Please quote ${reference} when making payment. Contact MBM if you need assistance.`)}</p></section><footer class="foot">${isReceipt?'This receipt confirms payment received for the rental period stated above.':'This invoice is generated from the linked agreement and charge record.'}<b>Integrity | Transparency | Professionalism | Reliability</b></footer></main></body></html>`;
  }
  function printReceipt(id){const payment=state.payments.find(item=>item.id===id);if(!payment)return;const agreement=lease(payment.leaseId),tenant=contact(agreement?.contactId),rentalUnit=unit(agreement?.unitId),propertyRecord=property(payment.propertyId||agreement?.propertyId);const invoice=state.invoices.find(item=>item.id===payment.chargeId)||state.invoices.find(item=>state.allocations.some(a=>a.paymentId===payment.id&&a.chargeId===item.id));const breakdown=invoiceBreakdown(invoice||{description:'Payment received',amount:payment.amount});const win=window.open('','_blank');if(!win)return alert('Your browser blocked the receipt window. Allow pop-ups and try again.');win.document.write(financialDocument({kind:'receipt',reference:payment.receiptNo,date:payment.paymentDate,tenant,agreement,rentalUnit,propertyRecord,period:payment.period,method:payment.method,lines:breakdown.lines,charges:breakdown.charges,credits:breakdown.credits,net:breakdown.net,paid:number(payment.amount),balance:invoice?chargeBalance(invoice):0,notes:payment.notes}));win.document.close();}
  function invoiceDocument(details){const {invoice,agreement,tenant,rentalUnit,propertyRecord,balance}=details,breakdown=invoiceBreakdown(invoice);return financialDocument({kind:'invoice',reference:invoice.invoiceNo,date:invoice.dueDate||invoice.chargeDate,tenant,agreement,rentalUnit,propertyRecord,period:invoice.billingPeriod||'',lines:breakdown.lines,charges:breakdown.charges,credits:breakdown.credits,net:breakdown.net,balance,notes:invoice.notes});}
  function backup(){audit(state,'Backup downloaded','Full MBM V19 JSON workspace backup created.');save();download(`MBM-Property-Manager-V19-backup-${today()}.json`,JSON.stringify(state,null,2));}
  function legacyMigration(){if(!confirm('Merge available V1–V9 browser data into the V10 workspace? Existing V10 records will remain.'))return;const legacy=migrateLegacy();['properties','units','contacts','leases','payments','municipalAccounts','workOrders','inspections','documents','renewals','calendarEvents','audit'].forEach(k=>{state[k].push(...legacy[k]);});audit(state,'V1–V9 migration run','Legacy records merged into V10. Review possible duplicate records.');save('V1–V9 data merged');render();}
  function resetWorkspace(){if(!confirm('Reset only the V10 local workspace? Your older MBM browser data is not deleted. Download a backup first.'))return;state=blankState();save('V10 workspace reset');render();}
  function quickAdd(){const menu=$('#quickAddMenu');menu.hidden=!menu.hidden;}
  function answerAssistant(question){const q=String(question||'').toLowerCase();const issues=complianceIssues();const opener='MBM checked the records currently stored in this browser. ';if(/arrears|receipt|payment|money|charge/.test(q))return `${opener}There are ${openCharges().length} open charge(s), totalling ${money(openChargeBalance())}. Go to Money to record a charge, receive a payment and allocate it to the correct charge.`;if(/municipal|water|electric/.test(q)){const overdue=state.municipalAccounts.filter(m=>m.dueDate&&diffDays(m.dueDate)<0&&Number(m.balance)>0);return `${opener}Municipal exposure is ${money(municipalOwing())} across ${state.municipalAccounts.length} linked account(s). ${overdue.length?`${overdue.length} account(s) are overdue and need action.`:'No municipal account is currently overdue.'}`;}if(/renew|expir|contract|lease/.test(q)){const items=leaseExpiry();return `${opener}${items.length} active agreement(s) expire within 90 days. ${items.slice(0,3).map(l=>`${leaseName(l.id)} (${diffDays(l.endDate)} days)`).join('; ')||'Record an expiry date on each active agreement so MBM can create a renewal action.'}`;}if(/service|maint|repair|work|inspection/.test(q))return `${opener}${openWork().length} work order(s) are open and ${state.inspections.filter(i=>i.status!=='Completed').length} inspection(s) are scheduled. Use Service Centre to assign a supplier, due date and cost.`;if(/vacan|tenant|occup/.test(q))return `${opener}${state.units.filter(u=>u.status==='Vacant').length} unit(s) are vacant, ${getActiveLeases().length} agreement(s) are active and ${state.prospects.filter(p=>!['Declined','Leased'].includes(p.stage)).length} prospect(s) are open.`;if(/attention|urgent|next|help/.test(q))return `${opener}${issues.length} control item(s) need review. ${issues.slice(0,3).map(i=>`${i.kind}: ${i.detail}`).join(' · ')||'Your monitored controls are currently clear.'}`;return `${opener}I can answer operational questions using your MBM records. Try: “What needs attention?”, “show arrears”, “which contracts are expiring?”, “municipal balance”, “open maintenance”, or “vacant units”.`}
